@page "/apply"
@rendermode InteractiveServer
@using sv_8785b7e25be440fb880a5c76e80645ce.Models
@using sv_8785b7e25be440fb880a5c76e80645ce.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < _stepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (stepIndex < _currentStep)
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@_stepNames[stepIndex]</div>
            </div>
            @if (i < _stepNames.Length - 1)
            {
                <div class="step-connector @(stepIndex < _currentStep ? "completed" : "")"></div>
            }
        }
    </div>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="error-message">@_errorMessage</div>
    }

    @* Step Content *@
    @if (_submitted)
    {
        <div class="confirmation">
            <h2>&#10003; Application Submitted!</h2>
            <p>Your application has been received. Your application ID is:</p>
            <p class="application-id"><strong>@_applicationId</strong></p>
            <p>Please save this ID for your records.</p>
        </div>
    }
    else
    {
        @switch (_currentStep)
        {
            case 0:
                @RenderPersonalInfo()
                break;
            case 1:
                @RenderWorkHistory()
                break;
            case 2:
                @RenderReferences()
                break;
            case 3:
                @RenderCoverLetter()
                break;
            case 4:
                @RenderReview()
                break;
        }
    }
</div>

@* Step 1: Personal Info *@
@{ RenderFragment RenderPersonalInfo() => @<div class="step-content">
    <h2>Personal Information</h2>
    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="_fullName" placeholder="Enter your full name" />
    </div>
    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="_email" placeholder="Enter your email" />
    </div>
    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="_phone" placeholder="Enter your phone number" />
    </div>
    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" @bind="_address" placeholder="Enter your address"></textarea>
    </div>
    <div class="form-actions">
        <button class="btn-next" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
            @if (_isValidating)
            {
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>;}

@* Step 2: Work History *@
@{ RenderFragment RenderWorkHistory() => @<div class="step-content">
    <h2>Work History</h2>
    @for (int i = 0; i < _workEntries.Count; i++)
    {
        var index = i;
        <div class="work-entry-card">
            <div class="work-entry-header">
                <h3>Position @(index + 1)</h3>
                @if (_workEntries.Count > 1)
                {
                    <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                }
            </div>
            <div class="form-group">
                <label>Company Name *</label>
                <input type="text" value="@_workEntries[index].Company"
                       @onchange="(e) => UpdateWorkEntry(index, company: e.Value?.ToString())" />
            </div>
            <div class="form-group">
                <label>Job Title *</label>
                <input type="text" value="@_workEntries[index].Title"
                       @onchange="(e) => UpdateWorkEntry(index, title: e.Value?.ToString())" />
            </div>
            <div class="form-row">
                <div class="form-group">
                    <label>Start Date *</label>
                    <input type="date" value="@_workEntries[index].StartDate.ToString("yyyy-MM-dd")"
                           @onchange="(e) => UpdateWorkEntryStartDate(index, e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>End Date</label>
                    <input type="date" value="@(_workEntries[index].EndDate?.ToString("yyyy-MM-dd"))"
                           disabled="@_workEntries[index].IsCurrent"
                           @onchange="(e) => UpdateWorkEntryEndDate(index, e.Value?.ToString())" />
                    <label class="checkbox-label">
                        <input type="checkbox" checked="@_workEntries[index].IsCurrent"
                               @onchange="(e) => ToggleCurrentJob(index, (bool)(e.Value ?? false))" />
                        Currently working here
                    </label>
                </div>
            </div>
            <div class="form-group">
                <label>Description</label>
                <textarea value="@_workEntries[index].Description"
                          @onchange="(e) => UpdateWorkEntry(index, description: e.Value?.ToString())"
                          placeholder="Describe your responsibilities..."></textarea>
            </div>
        </div>
    }
    <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
    <div class="form-actions">
        <button class="btn-back" @onclick="PreviousStep">Back</button>
        <button class="btn-next" @onclick="NextFromWorkHistory">Next</button>
    </div>
</div>;}

@* Step 3: References *@
@{ RenderFragment RenderReferences() => @<div class="step-content">
    <h2>References</h2>
    @for (int i = 0; i < _references.Count; i++)
    {
        var index = i;
        <div class="reference-card">
            <div class="work-entry-header">
                <h3>Reference @(index + 1)</h3>
                @if (_references.Count > 2)
                {
                    <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>
            <div class="form-row">
                <div class="form-group">
                    <label>Name *</label>
                    <input type="text" value="@_references[index].Name"
                           @onchange="(e) => UpdateReference(index, name: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Relationship *</label>
                    <input type="text" value="@_references[index].Relationship"
                           @onchange="(e) => UpdateReference(index, relationship: e.Value?.ToString())" />
                </div>
            </div>
            <div class="form-row">
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" value="@_references[index].Email"
                           @onchange="(e) => UpdateReference(index, email: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" value="@_references[index].Phone"
                           @onchange="(e) => UpdateReference(index, phone: e.Value?.ToString())" />
                </div>
            </div>
        </div>
    }
    @if (_references.Count < 3)
    {
        <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
    }
    <div class="form-actions">
        <button class="btn-back" @onclick="PreviousStep">Back</button>
        <button class="btn-next" @onclick="NextFromReferences">Next</button>
    </div>
</div>;}

@* Step 4: Cover Letter *@
@{ RenderFragment RenderCoverLetter() => @<div class="step-content">
    <h2>Cover Letter</h2>
    <div class="form-group">
        <label for="coverLetter">Write your cover letter below:</label>
        <textarea id="coverLetter" class="cover-letter-input" @bind="_coverLetter" @bind:event="oninput"
                  maxlength="2000" placeholder="Tell us why you're a great fit for this role..."></textarea>
        <div class="character-count @(_coverLetter.Length > 1800 ? "warning" : "")">
            @_coverLetter.Length / 2000 characters
        </div>
    </div>
    <div class="form-actions">
        <button class="btn-back" @onclick="PreviousStep">Back</button>
        <button class="btn-next" @onclick="NextFromCoverLetter">Next</button>
    </div>
</div>;}

@* Step 5: Review & Submit *@
@{ RenderFragment RenderReview() => @<div class="step-content">
    <h2>Review & Submit</h2>

    <div class="review-section">
        <div class="review-header">
            <h3>Personal Information</h3>
            <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
        </div>
        <dl class="review-list">
            <dt>Full Name</dt><dd>@_fullName</dd>
            <dt>Email</dt><dd>@_email</dd>
            <dt>Phone</dt><dd>@_phone</dd>
            <dt>Address</dt><dd>@_address</dd>
        </dl>
    </div>

    <div class="review-section">
        <div class="review-header">
            <h3>Work History</h3>
            <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
        </div>
        @foreach (var entry in _workEntries)
        {
            <div class="review-work-entry">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <br />
                <span class="review-dates">
                    @entry.StartDate.ToString("MMM yyyy") —
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                </span>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p class="review-description">@entry.Description</p>
                }
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-header">
            <h3>References</h3>
            <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
        </div>
        @foreach (var reference in _references)
        {
            <div class="review-reference">
                <strong>@reference.Name</strong> (@reference.Relationship)
                <br />
                <span>@reference.Email | @reference.Phone</span>
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-header">
            <h3>Cover Letter</h3>
            <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
        </div>
        <p class="review-cover-letter">@_coverLetter</p>
    </div>

    <div class="form-actions">
        <button class="btn-back" @onclick="PreviousStep">Back</button>
        <button class="btn-submit" @onclick="SubmitApplication" disabled="@_isSubmitting">
            @if (_isSubmitting)
            {
                <span>Submitting...</span>
            }
            else
            {
                <span>Submit Application</span>
            }
        </button>
    </div>
</div>;}

@code {
    private static readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int _currentStep = 0;
    private bool _isValidating = false;
    private bool _isSubmitting = false;
    private bool _submitted = false;
    private int _applicationId;
    private string _errorMessage = string.Empty;

    // Step 1 - Personal Info
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2 - Work History
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3 - References
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 - Cover Letter
    private string _coverLetter = string.Empty;

    private string GetStepClass(int step)
    {
        if (step == _currentStep) return "active";
        if (step < _currentStep) return "completed";
        return "future";
    }

    private void NavigateToStep(int step)
    {
        if (step < _currentStep)
        {
            _currentStep = step;
            _errorMessage = string.Empty;
        }
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
        _errorMessage = string.Empty;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
        {
            _currentStep--;
            _errorMessage = string.Empty;
        }
    }

    private async Task NextFromPersonalInfo()
    {
        _errorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
            string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        _isValidating = true;
        try
        {
            var isValidEmail = await ApplicationService.ValidateEmailAsync(_email);
            if (!isValidEmail)
            {
                _errorMessage = "Please enter a valid email address.";
                return;
            }
            _currentStep++;
        }
        finally
        {
            _isValidating = false;
        }
    }

    private void NextFromWorkHistory()
    {
        _errorMessage = string.Empty;

        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default)
            {
                _errorMessage = "Please fill in company name, job title, and start date for all positions.";
                return;
            }
        }
        _currentStep++;
    }

    private void NextFromReferences()
    {
        _errorMessage = string.Empty;

        foreach (var reference in _references)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                _errorMessage = "Please fill in all fields for each reference.";
                return;
            }
        }
        _currentStep++;
    }

    private void NextFromCoverLetter()
    {
        _errorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(_coverLetter))
        {
            _errorMessage = "Please write a cover letter.";
            return;
        }
        _currentStep++;
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _errorMessage = string.Empty;

        try
        {
            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
            var workEntries = _workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList();
            var work = new WorkHistory(workEntries);
            var references = _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, work, references, _coverLetter);
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    // Work entry helpers
    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
            _workEntries.RemoveAt(index);
    }

    private void UpdateWorkEntry(int index, string? company = null, string? title = null, string? description = null)
    {
        var entry = _workEntries[index];
        if (company != null) entry.Company = company;
        if (title != null) entry.Title = title;
        if (description != null) entry.Description = description;
    }

    private void UpdateWorkEntryStartDate(int index, string? value)
    {
        if (DateTime.TryParse(value, out var date))
            _workEntries[index].StartDate = date;
    }

    private void UpdateWorkEntryEndDate(int index, string? value)
    {
        if (DateTime.TryParse(value, out var date))
            _workEntries[index].EndDate = date;
    }

    private void ToggleCurrentJob(int index, bool isCurrent)
    {
        _workEntries[index].IsCurrent = isCurrent;
        if (isCurrent)
            _workEntries[index].EndDate = null;
    }

    // Reference helpers
    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private void UpdateReference(int index, string? name = null, string? relationship = null, string? email = null, string? phone = null)
    {
        var r = _references[index];
        if (name != null) r.Name = name;
        if (relationship != null) r.Relationship = relationship;
        if (email != null) r.Email = email;
        if (phone != null) r.Phone = phone;
    }

    // Mutable models for form state
    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

