arguments.file_text:
.application-form {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1.5rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 3px solid #ddd;
    background: white;
    color: #999;
    transition: all 0.3s ease;
}

.step.active .step-circle {
    border-color: #4361ee;
    background: #4361ee;
    color: white;
}

.step.completed .step-circle {
    border-color: #2ecc71;
    background: #2ecc71;
    color: white;
}

.step.future .step-circle {
    border-color: #ddd;
    background: #f8f9fa;
    color: #999;
}

.checkmark {
    font-size: 1rem;
}

.step-label {
    margin-top: 0.5rem;
    font-size: 0.75rem;
    text-align: center;
    color: #666;
    white-space: nowrap;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ecc71;
}

.step-connector {
    flex: 1;
    height: 3px;
    background: #ddd;
    margin: 0 0.25rem;
    margin-bottom: 1.5rem;
    max-width: 60px;
    transition: background 0.3s ease;
}

.step-connector.completed {
    background: #2ecc71;
}

/* Step Content */
.step-content {
    background: white;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
    border: 1px solid #eee;
}

.step-content h2 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
    border-bottom: 2px solid #f0f0f0;
    padding-bottom: 0.75rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.7rem 0.9rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
}

.form-group textarea {
    min-height: 80px;
    resize: vertical;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    margin-top: 0.5rem;
    font-weight: normal !important;
    font-size: 0.85rem !important;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.form-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #f0f0f0;
}

.btn-next,
.btn-submit {
    padding: 0.7rem 2rem;
    background: #4361ee;
    color: white;
    border: none;
    border-radius: 6px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s;
    margin-left: auto;
}

.btn-next:hover,
.btn-submit:hover {
    background: #3451d1;
}

.btn-next:disabled,
.btn-submit:disabled {
    background: #a0aec0;
    cursor: not-allowed;
}

.btn-back {
    padding: 0.7rem 2rem;
    background: transparent;
    color: #666;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-back:hover {
    background: #f8f9fa;
    border-color: #999;
}

.btn-add {
    display: block;
    width: 100%;
    padding: 0.7rem;
    background: #f8f9fa;
    color: #4361ee;
    border: 2px dashed #4361ee;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    margin-top: 1rem;
    transition: background 0.2s;
}

.btn-add:hover {
    background: #eef2ff;
}

.btn-remove {
    padding: 0.3rem 0.8rem;
    background: transparent;
    color: #e74c3c;
    border: 1px solid #e74c3c;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-remove:hover {
    background: #e74c3c;
    color: white;
}

.btn-edit {
    padding: 0.3rem 0.8rem;
    background: transparent;
    color: #4361ee;
    border: 1px solid #4361ee;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-edit:hover {
    background: #4361ee;
    color: white;
}

/* Work Entry & Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #fafbfc;
}

.work-entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #333;
}

/* Cover Letter */
.cover-letter-input {
    min-height: 250px !important;
    font-family: inherit;
    line-height: 1.6;
}

.character-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.4rem;
}

.character-count.warning {
    color: #e67e22;
    font-weight: 500;
}

/* Review Section */
.review-section {
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafbfc;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #1a1a2e;
}

.review-list {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-list dt {
    font-weight: 500;
    color: #666;
    font-size: 0.9rem;
}

.review-list dd {
    margin: 0;
    color: #333;
    font-size: 0.9rem;
}

.review-work-entry {
    padding: 0.75rem 0;
    border-bottom: 1px solid #eee;
}

.review-work-entry:last-child {
    border-bottom: none;
}

.review-dates {
    font-size: 0.85rem;
    color: #666;
}

.review-description {
    margin: 0.4rem 0 0;
    font-size: 0.85rem;
    color: #555;
}

.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #eee;
    font-size: 0.9rem;
}

.review-reference:last-child {
    border-bottom: none;
}

.review-cover-letter {
    white-space: pre-wrap;
    font-size: 0.9rem;
    color: #333;
    line-height: 1.6;
    margin: 0;
}

/* Error Message */
.error-message {
    background: #ffeaea;
    color: #c0392b;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-bottom: 1rem;
    font-size: 0.9rem;
    border: 1px solid #f5c6cb;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 2rem;
    background: white;
    border-radius: 12px;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
    border: 1px solid #eee;
}

.confirmation h2 {
    color: #2ecc71;
    font-size: 1.8rem;
    margin-bottom: 1rem;
}

.application-id {
    font-size: 2rem;
    color: #4361ee;
    margin: 1rem 0;
}

/* Responsive */
@media (max-width: 600px) {
    .step-indicator {
        flex-wrap: wrap;
    }

    .step-label {
        font-size: 0.65rem;
    }

