+    padding: 0.5rem 0;
+    border-bottom: 1px solid #eee;
+    font-size: 0.9rem;
+}
+
+.review-reference:last-child {
+    border-bottom: none;
+}
+
+.review-cover-letter {
+    white-space: pre-wrap;
+    font-size: 0.9rem;
+    color: #333;
+    line-height: 1.6;
+    margin: 0;
+}
+
+/* Error Message */
+.error-message {
+    background: #ffeaea;
+    color: #c0392b;
+    padding: 0.75rem 1rem;
+    border-radius: 6px;
+    margin-bottom: 1rem;
+    font-size: 0.9rem;
+    border: 1px solid #f5c6cb;
+}
+
+/* Confirmation */
+.confirmation {
+    text-align: center;
+    padding: 3rem 2rem;
+    background: white;
+    border-radius: 12px;
+    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
+    border: 1px solid #eee;
+}
+
+.confirmation h2 {
+    color: #2ecc71;
+    font-size: 1.8rem;
+    margin-bottom: 1rem;
+}
+
+.application-id {
+    font-size: 2rem;
+    color: #4361ee;
+    margin: 1rem 0;
+}
+
+/* Responsive */
+@media (max-width: 600px) {
+    .step-indicator {
+        flex-wrap: wrap;
+    }
+
+    .step-label {
+        font-size: 0.65rem;
+    }
+
+    .form-row {
+        grid-template-columns: 1fr;
+    }
+
+    .step-connector {
+        display: none;
+    }
+}
+
